12	/// Fetches the full, unfiltered list of every tag name in the repository at
13	/// `root`, via [`GitAccess`] (native gix, falling back to a `CommandRunner`-
14	/// shelled `git tag --list` when gix is unavailable -- most notably on
15	/// `wasm32`).
16	///
17	/// Deliberately fetches with no glob pattern: callers filter afterwards
18	/// via [`matching_tags`], using the same `globset` matcher both
19	/// `GitDataSource` backends use internally -- identical tag-selection
20	/// semantics regardless of backend, and lets the fetch batch once across
21	/// every package (see [`TagIndex::build`]) instead of once per package,
22	/// important on `wasm32` where each `CommandRunner` call is a full Extism
23	/// round-trip.
24	fn fetch_all_tags(git: &GitAccess<'_>) -> Result<Vec<String>, GraphError> {
25	    let tags = git.list_tags(None)?;
26	    Ok(tags.into_iter().map(|t| t.as_str().to_string()).collect())
27	}
28	
29	/// Filters `all_tags` down to those matching `template`'s glob.
30	///
31	/// Compiles the glob via [`callisto_vcs::compile_tag_glob`] -- the same
32	/// shared helper both `GitDataSource` backends (`GitRepository::list_tags`,
33	/// `ShellGit::list_tags`) use internally -- so tag selection is
34	/// byte-identical whether `all_tags` came from gix or the `CommandRunner`
35	/// fallback in [`fetch_all_tags`]. Includes error behavior: a
36	/// `template.glob()` that fails to compile surfaces as
37	/// `Err(GraphError::Vcs(VcsError::InvalidGlob))` -- matching every tag is
38	/// the unsafe alternative, since a malformed template must never silently
39	/// make "last tag" resolution pick an unrelated package's tag.
40	fn matching_tags<'a>(all_tags: &'a [String], template: &TagTemplate) -> Result<Vec<&'a str>, GraphError> {
41	    let glob = template.glob();
42	    GLOB_COMPILE_COUNT.fetch_add(1, std::sync::atomic::Ordering::SeqCst);
43	    let matcher = callisto_vcs::compile_tag_glob(&glob).map_err(GraphError::Vcs)?;
44	
45	    Ok(all_tags
46	        .iter()
47	        .filter(|t| matcher.is_match(t.as_str()))
48	        .map(|s| s.as_str())
49	        .collect())
50	}
51	
52	/// Test-observability counter: total number of times [`matching_tags`] has
53	/// compiled a fresh `globset::Glob`. Production code never reads this; it
54	/// exists so tests can assert `TagIndex::build` compiles/scans at most once
55	/// per *distinct* tag-template glob, not once per package -- a
56	/// `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template` can
57	/// apply the identical template string to many packages at once.
58	static GLOB_COMPILE_COUNT: std::sync::atomic::AtomicUsize = std::sync::atomic::AtomicUsize::new(0);
59	
60	/// Resets the internal glob-compile call counter to zero. Intended for use in test setup.
61	///
62	/// Process-global, like `callisto_manifests::reset_open_call_count` -- exact
63	/// counts must be asserted from an isolated integration-test binary under
64	/// `#[serial]`, not an inline unit test sharing this crate's `--lib`
65	/// process with other, non-serial tests (see
66	/// `tests/tag_glob_cache_count_test.rs`).
67	pub fn reset_glob_compile_count() {
68	    GLOB_COMPILE_COUNT.store(0, std::sync::atomic::Ordering::SeqCst);
69	}
70	
71	/// Reads the current value of the internal glob-compile call counter.
72	pub fn glob_compile_count() -> usize {
73	    GLOB_COMPILE_COUNT.load(std::sync::atomic::Ordering::SeqCst)
74	}
