76	/// Selects the highest-versioned tag matching `template` out of a full tag
77	/// list previously obtained via [`fetch_all_tags`], reusing a `cache` of
78	/// already-compiled/already-scanned candidates keyed by `template.glob()`
79	/// -- a `[[package-set]]` rule with a fixed (non-`{name}`) `tag-template`
80	/// string applies the identical template to every matching package, so
81	/// without this cache `TagIndex::build`'s per-package loop would recompile
82	/// the same `globset::Glob` and rescan the full tag list once per package
83	/// sharing that template, instead of once per distinct template.
84	fn select_from_tags_cached<'a>(
85	    all_tags: &'a [String],
86	    template: &TagTemplate,
87	    grammar: VersionGrammar,
88	    cache: &mut std::collections::HashMap<String, Vec<&'a str>>,
89	) -> Result<LastTagSelection, GraphError> {
90	    let glob = template.glob();
91	    let candidates = match cache.get(&glob) {
92	        Some(cached) => cached.clone(),
93	        None => {
94	            let matched = matching_tags(all_tags, template)?;
95	            cache.insert(glob, matched.clone());
96	            matched
97	        }
98	    };
99	    select_last_tag(template, grammar, candidates).map_err(GraphError::from)
100	}
