102	pub struct TagIndex {
103	    last: BTreeMap<PackageId, Option<LastTag>>,
104	    templates: BTreeMap<PackageId, TagTemplate>,
105	    pre_cursor: BTreeMap<PackageId, Option<CommitSha>>,
106	    /// The full, unfiltered raw tag list fetched once during `build` (see
107	    /// `fetch_all_tags`), kept around so callers checking whether a specific
108	    /// tag name already exists (e.g. `create_tags_with_options`, once per
109	    /// release) can consult this in-memory set instead of re-querying `git`
110	    /// once per check.
111	    all_tags: std::collections::BTreeSet<String>,
112	    pub diagnostics: Vec<Diagnostic>,
113	}
114	
115	impl TagIndex {
116	    pub fn build<D: DependencyResolver>(
117	        git: &GitAccess<'_>,
118	        graph: &D,
119	        _cfg: &ResolvedConfig,
120	    ) -> Result<Self, GraphError> {
121	        let mut last = BTreeMap::new();
122	        let mut templates = BTreeMap::new();
123	        let mut pre_cursor = BTreeMap::new();
124	        let diagnostics = Vec::new();
125	
126	        // Fetch the raw tag list exactly once for the whole build, not once
127	        // per package -- see `fetch_all_tags` for why (avoids N gix
128	        // discoveries / N host round-trips for N packages). `git` is shared
129	        // with the caller rather than discovered fresh here, so a single
130	        // `Workspace`-scoped command that also needs git for other reasons
131	        // (e.g. `plan_publish`'s head_sha resolution) doesn't pay for a
132	        // second discovery.
133	        let all_tags = fetch_all_tags(git)?;
134	        let all_tags_set: std::collections::BTreeSet<String> = all_tags.iter().cloned().collect();
135	        let mut glob_cache: std::collections::HashMap<String, Vec<&str>> = std::collections::HashMap::new();
136	
137	        for pkg in graph.packages() {
138	            let default_tmpl = TagTemplate::parse(&format!("{}@{{version}}", pkg.id.display_name()))?;
139	            let tmpl = pkg.tag_template.clone().unwrap_or(default_tmpl);
140	            let sel = select_from_tags_cached(&all_tags, &tmpl, pkg.version_grammar()?, &mut glob_cache)?;
141	            last.insert(pkg.id.clone(), sel.chosen);
142	            templates.insert(pkg.id.clone(), tmpl);
143	            pre_cursor.insert(pkg.id.clone(), None);
144	        }
145	
146	        Ok(TagIndex {
147	            last,
148	            templates,
149	            pre_cursor,
150	            all_tags: all_tags_set,
151	            diagnostics,
152	        })
153	    }
154	
155	    pub fn last_tag(&self, id: &PackageId) -> Option<&LastTag> {
156	        self.last.get(id).and_then(|opt| opt.as_ref())
157	    }
158	
159	    pub fn template(&self, id: &PackageId) -> &TagTemplate {
160	        &self.templates[id]
161	    }
162	
163	    pub fn pre_cursor(&self, id: &PackageId) -> Option<&CommitSha> {
164	        self.pre_cursor.get(id).and_then(|opt| opt.as_ref())
165	    }
