167	    /// Returns whether `tag_name` is present in the raw tag list fetched
168	    /// during `build` -- an exact match, not a glob. Lets callers checking
169	    /// tag existence once per release (e.g. `create_tags_with_options`)
170	    /// consult this in-memory set instead of shelling out to `git` again
171	    /// for each one.
172	    pub fn contains_tag(&self, tag_name: &str) -> bool {
173	        self.all_tags.contains(tag_name)
174	    }
