179	        TagIndex {
180	            last: BTreeMap::new(),
181	            templates: BTreeMap::new(),
182	            pre_cursor: BTreeMap::new(),
183	            all_tags: std::collections::BTreeSet::new(),
184	            diagnostics: Vec::new(),
185	        }
186	    }
187	}
