229	    /// A `CommandRunner` double that never touches a real `git` binary: it
230	    /// answers `git tag --list` with a canned tag list and counts every
231	    /// invocation. Used both to prove `TagIndex::build` succeeds with gix
232	    /// unavailable (mirroring the wasm32 code path, where
233	    /// `GitRepository::discover` always fails), and to count how many
234	    /// `CommandRunner` round-trips a `TagIndex::build` call costs.
235	    struct FakeGitTagRunner {
236	        calls: AtomicUsize,
237	        tags: Vec<String>,
238	    }
239	
240	    impl FakeGitTagRunner {
241	        fn new(tags: Vec<String>) -> Self {
242	            FakeGitTagRunner {
243	                calls: AtomicUsize::new(0),
244	                tags,
245	            }
246	        }
