249	    impl CommandRunner for FakeGitTagRunner {
250	        fn run(&self, program: &str, args: &[&str], _cwd: &Path) -> Result<CommandOutput, CommandError> {
251	            assert_eq!(program, "git");
252	            assert_eq!(args, ["tag", "--list"]);
253	            self.calls.fetch_add(1, Ordering::SeqCst);
254	            Ok(CommandOutput {
255	                exit_code: Some(0),
256	                stdout: self.tags.join("\n"),
257	                stderr: String::new(),
258	            })
259	        }
