331	    /// Spec: on a real, gix-discoverable repo, `matching_tags` must select
332	    /// exactly the tags `callisto_vcs::GitRepository::list_tags`'s own
333	    /// glob-based filtering would -- proving the two paths share identical
334	    /// selection semantics.
335	    #[test]
336	    fn test_matching_tags_mirrors_globset_semantics() {
337	        let all = vec![
338	            "pkg-a@1.0.0".to_string(),
339	            "pkg-ab@1.0.0".to_string(),
340	            "pkg-a@2.0.0-beta".to_string(),
341	            "other".to_string(),
342	        ];
343	        let tmpl = TagTemplate::parse("pkg-a@{version}").unwrap();
344	        let matched = matching_tags(&all, &tmpl).unwrap();
345	        assert_eq!(matched, vec!["pkg-a@1.0.0", "pkg-a@2.0.0-beta"]);
