348	    /// Spec: a `TagTemplate` whose glob fails to compile must make
349	    /// `matching_tags` return `Err`, not silently disable filtering and
350	    /// match every tag in the repo. `TagTemplate::parse` only rejects
351	    /// `*`/`?`/`[`/`]` in literal text -- it does not reject unbalanced
352	    /// `{`/`}`, so a template like `pkg-a@{version}{oops` parses
353	    /// successfully but renders the glob `pkg-a@*{oops`, which `globset`
354	    /// cannot compile (unclosed alternate group). This is a real
355	    /// correctness risk for release tagging: silently matching every tag
356	    /// could make "last tag" resolution pick an unrelated package's tag.
357	    #[test]
358	    fn test_matching_tags_rejects_malformed_glob_instead_of_matching_everything() {
359	        let all = vec![
360	            "pkg-a@1.0.0".to_string(),
361	            "totally-unrelated-tag".to_string(),
362	            "another-unrelated-tag".to_string(),
363	        ];
364	        let tmpl = TagTemplate::parse("pkg-a@{version}{oops").unwrap();
365	        // Sanity-check the premise: this template's glob really is
366	        // uncompilable.
367	        assert!(globset::Glob::new(&tmpl.glob()).is_err());
368	
369	        let result = matching_tags(&all, &tmpl);
370	
371	        assert!(
372	            matches!(result, Err(GraphError::Vcs(callisto_vcs::VcsError::InvalidGlob { .. }))),
373	            "malformed glob must be surfaced as Err, not silently match every tag; got {result:?}"
374	        );
375	    }
