7	/// A validated tag template containing prefix, suffix, and exact `{version}` placement.
8	#[derive(Clone, Debug, PartialEq, Eq, Hash)]
9	pub struct TagTemplate {
10	    prefix: String,
11	    suffix: String,
12	}
