14	impl TagTemplate {
15	    pub fn parse(raw: &str) -> Result<Self, TagTemplateError> {
16	        let version_marker = "{version}";
17	        let count = raw.matches(version_marker).count();
18	        if count == 0 {
19	            if let Some(start) = raw.find('{') {
20	                if let Some(end) = raw[start..].find('}') {
21	                    let placeholder = &raw[start + 1..start + end];
22	                    return Err(TagTemplateError::UnknownPlaceholder {
23	                        template: raw.to_string(),
24	                        placeholder: placeholder.to_string(),
25	                    });
26	                }
27	            }
28	            return Err(TagTemplateError::MissingVersionPlaceholder {
29	                template: raw.to_string(),
30	            });
31	        }
32	        if count > 1 {
33	            return Err(TagTemplateError::MultipleVersionPlaceholders {
34	                template: raw.to_string(),
35	                count,
36	            });
37	        }
38	
39	        let (prefix, suffix) = raw.split_once(version_marker).unwrap();
40	
41	        if prefix.is_empty() && suffix.is_empty() {
42	            return Err(TagTemplateError::NoLiteralAnchor {
43	                template: raw.to_string(),
44	            });
45	        }
46	
47	        for (part, _name) in [(prefix, "prefix"), (suffix, "suffix")] {
48	            for ch in part.chars() {
49	                if matches!(ch, '*' | '?' | '[' | ']') {
50	                    return Err(TagTemplateError::GlobMetacharacterInLiteral {
51	                        template: raw.to_string(),
52	                        ch,
53	                    });
54	                }
55	            }
56	        }
57	
58	        let test_render = format!("{prefix}1.0.0{suffix}");
59	        if !is_valid_git_ref_name(&test_render) {
60	            return Err(TagTemplateError::InvalidGitRefName {
61	                template: raw.to_string(),
62	                rendered: test_render,
63	            });
64	        }
65	
66	        Ok(TagTemplate {
67	            prefix: prefix.to_string(),
68	            suffix: suffix.to_string(),
69	        })
70	    }
71	
72	    pub fn default_for(id: &PackageId) -> Self {
73	        TagTemplate {
74	            prefix: format!("{}@", id.display_name()),
75	            suffix: String::new(),
76	        }
77	    }
78	
79	    pub fn render(&self, version: &Version) -> TagName {
80	        // Unchecked: `prefix`/`suffix` already passed `is_valid_git_ref_name`
81	        // against a `1.0.0` stand-in at `TagTemplate::parse` time (rejecting
82	        // a leading `-`, control characters, `..`, `@{`, and per-component
83	        // `.lock` suffixes on that literal). `version.render()` is
84	        // Callisto's own trusted SemVer/PEP 440 rendering, never
85	        // attacker-controlled text, and its first character is always a
86	        // digit -- never `-` or a control character. That probe cannot rule
87	        // out every conceivable rendered version (for example, build
88	        // metadata literally ending in `.lock`), but it does rule out the
89	        // flag-injection-relevant leading-`-` and control-character cases
90	        // `TagName::parse` exists to catch.
91	        TagName::new_unchecked(format!("{}{}{}", self.prefix, version.render(), self.suffix))
92	    }
93	
94	    pub fn render_floating_major(&self, version: &Version) -> Option<TagName> {
95	        let major = version.major()?;
96	        let rendered = format!("{}{}{}", self.prefix, major, self.suffix);
97	        TagName::parse(&rendered).ok()
98	    }
99	
100	    pub fn glob(&self) -> String {
101	        format!("{}*{}", self.prefix, self.suffix)
102	    }
103	
104	    pub fn extract_version_str<'a>(&self, tag: &'a str) -> Option<&'a str> {
105	        if !tag.starts_with(&self.prefix) || !tag.ends_with(&self.suffix) {
106	            return None;
107	        }
108	        let end_idx = tag.len() - self.suffix.len();
109	        if end_idx < self.prefix.len() {
110	            return None;
111	        }
112	        Some(&tag[self.prefix.len()..end_idx])
113	    }
114	
115	    pub fn as_str(&self) -> String {
116	        format!("{}{{version}}{}", self.prefix, self.suffix)
117	    }
118	}
