242	/// Output of last_tag_for pure selection algorithm.
243	#[derive(Clone, Debug, Default)]
244	pub struct LastTagSelection {
245	    pub chosen: Option<LastTag>,
246	    pub skipped: Vec<Diagnostic>,
247	}
248	
249	/// Pure tag selection algorithm.
250	pub fn select_last_tag<'a>(
251	    template: &TagTemplate,
252	    grammar: VersionGrammar,
253	    candidates: impl IntoIterator<Item = &'a str>,
254	) -> Result<LastTagSelection, VersionParseError> {
255	    let mut chosen: Option<LastTag> = None;
256	    let mut skipped = Vec::new();
257	
258	    for candidate in candidates {
259	        let Some(extracted) = template.extract_version_str(candidate) else {
260	            continue;
261	        };
262	
263	        match Version::parse(extracted, grammar) {
264	            Ok(ver) => {
265	                let tag = LastTag {
266	                    // Unchecked: `candidate` matched `template`'s
267	                    // already-validated prefix/suffix (see
268	                    // `TagTemplate::render`'s justification) surrounding
269	                    // `extracted`, which just parsed successfully as a
270	                    // `grammar` version -- the same trusted, non-`-`-leading
271	                    // charset as `Version::render()`.
272	                    name: TagName::new_unchecked(candidate.to_string()),
273	                    version: ver,
274	                };
275	                match &chosen {
276	                    None => chosen = Some(tag),
277	                    Some(prev) => {
278	                        let ord = tag.version.compare(&prev.version).map_err(|_err| VersionParseError {
279	                            raw: extracted.to_string(),
280	                            grammar,
281	                            message: "grammar mismatch during candidate selection".to_string(),
282	                        })?;
283	                        match ord {
284	                            std::cmp::Ordering::Greater => chosen = Some(tag),
285	                            std::cmp::Ordering::Equal => {
286	                                if tag.name.as_str() > prev.name.as_str() {
287	                                    chosen = Some(tag);
288	                                }
289	                            }
290	                            std::cmp::Ordering::Less => {}
291	                        }
292	                    }
293	                }
294	            }
295	            Err(_) => {
296	                skipped.push(Diagnostic {
297	                    code: DiagnosticCode::TagGlobNonVersionMatch,
298	                    severity: DiagnosticSeverity::Warning,
299	                    message: format!(
300	                        "tag candidate `{candidate}` matched glob but placeholder `{extracted}` is not a valid {grammar:?} version"
301	                    ),
302	                    package: None,
303	                    path: None,
304	                    escalated_by: None,
305	                    governed_by: None,
306	                });
307	            }
308	        }
309	    }
310	
311	    Ok(LastTagSelection { chosen, skipped })
312	}
